'use strict';

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var SharedArrayBuffer = require( '@stdlib/array/shared-buffer' );
var Symbol = require( '@stdlib/symbol/ctor' );
var getGlobal = require( '@stdlib/utils/global' );
var main = require( './../lib/main.js' );
var publicMain = require( './../lib' );
var common = require( './common.js' );

tape('main export is a function', function test(t) {
	t.ok( true, __filename );
	t.strictEqual(typeof publicMain, 'function');
	t.end();
});

tape( 'public routes reject shared backing storage before writes', {
	'skip': SharedArrayBuffer === null
}, function test( t ) {
	var routes;
	var clone;
	var whole;
	var a;
	var e;
	var p;
	whole = new SharedArrayBuffer( 128 );
	clone = getGlobal().structuredClone;
	clone = ( clone ) ? clone( whole ) : whole;
	a = new Float64Array( whole, 0, 4 );
	e = new Float64Array( clone, 16, 2 );
	p = new Int32Array( [ -1, -2 ] );
	a.set( [ 1, 92, 3, 4 ] );
	routes = [ main, publicMain ];
	routes.forEach( function eachRoute( fn ) {
		t.throws( function call() {
			fn( 'column-major', 'upper', 'convert', 2, a, 2, e, p );
		}, TypeError, 'shared identity cannot establish disjoint storage' );
		t.deepEqual( a, new Float64Array( [ 1, 92, 3, 4 ] ), 'no A writes' );
		if ( Symbol.toStringTag ) {
			Object.defineProperty( whole, Symbol.toStringTag, {
				'value': 'ArrayBuffer',
				'configurable': true
			});
			t.throws( function call() {
				fn( 'column-major', 'upper', 'convert', 2, a, 2, e, p );
			}, TypeError, 'spoofed tag cannot replace intrinsic branding' );
		}
	} );
	t.end();
} );

tape('JavaScript factor storage matches actual pinned ROOK/RK directional fixtures', function test(t) {
	common.corpus(t, main);
	t.end();
});
tape('public main supports both padded major orders', function test(t) {
	var order;
	var lda;
	var a;
	var e;
	var f;
	var i;
	var j;
	var k;
	var n;
	var p;
	var s;
	var x;
	for (k = 0; k < common.fixtures.length; k++) {
		f = common.fixtures[k];
		n = f.n;
		if (n === 0) {
			continue;
		}
		for (x = 0; x < 2; x++) {
			order = ( x ) ? 'row-major' : 'column-major';
			lda = n + 2;
			a = new Float64Array(lda * n);
			e = new Float64Array(n);
			p = new Int32Array(f.ipiv_signed_1based);
			s = common.pack(f, ( x ) ? lda : 1, ( x ) ? 1 : lda, 1, 1);
			for (j = 0; j < n; j++) {
				for (i = 0; i < n; i++) {
					a[( x ) ? (i * lda) + j : i + (j * lda)] = s.args[3][s.args[6] + (i * s.args[4]) + (j * s.args[5])];
				}
				e[j] = s.args[7][s.args[9] + j];
			}
			t.strictEqual(publicMain(order, s.args[0], s.args[1], n, a, lda, e, p), 0, f.id + ' ' + order);
			for (j = 0; j < n; j++) {
				for (i = 0; i < n; i++) {
					s.a[3 + s.args[6] + (i * s.args[4]) + (j * s.args[5])] = a[( x ) ? (i * lda) + j : i + (j * lda)];
				}
				s.e[3 + s.args[9] + j] = e[j];
			}
			t.ok(common.equal(s.a, s.expectedA), 'full A');
			t.ok(common.equal(s.e, s.expectedE), 'full E');
			t.deepEqual(p, new Int32Array(f.ipiv_signed_1based), 'unchanged pivots');
		}
	}
	t.end();
});
tape('malformed pivots and indexed metadata reject before routine writes', function test(t) {
	var bad;
	var a;
	var e;
	var i;
	var p;
	bad = [
		[
			0,
			2
		],
		[
			-1,
			2
		],
		[
			1,
			-2
		],
		[
			-2147483648,
			-1
		],
		[
			3,
			2
		],
		[
			-3,
			-2
		]
	];
	for (i = 0; i < bad.length; i++) {
		a = new Float64Array([
			1,
			91,
			3,
			4
		]);
		e = new Float64Array([
			8,
			9
		]);
		p = new Int32Array(bad[i]);
		t.throws(publicMain.bind(null, 'column-major', 'upper', 'convert', 2, a, 2, e, p), RangeError);
		t.deepEqual(a, new Float64Array([
			1,
			91,
			3,
			4
		]), 'no A writes');
		t.deepEqual(e, new Float64Array([
			8,
			9
		]), 'no E writes');
	}
	a = new Float64Array(16);
	e = new Float64Array(4);
	p = new Int32Array([
		1,
		2,
		3,
		4
	]);
	t.throws(function call() {
		publicMain.ndarray('upper', 'convert', 4, a, 1, 1, 0, e, 1, 0, p, 1, 0);
	}, RangeError, 'matrix collisions');
	t.throws(function call() {
		publicMain.ndarray('upper', 'convert', 4, a, 1, 4, 0, e, 0, 0, p, 1, 0);
	}, RangeError, 'mutable broadcast E');
	t.throws(function call() {
		publicMain.ndarray('upper', 'convert', 4, a, 9007199254740991, 4, 0, e, 1, 0, p, 1, 0);
	}, RangeError, 'inexact indexing');
	t.deepEqual(a, new Float64Array(16), 'invalid indexing never writes A');
	t.deepEqual(e, new Float64Array(4), 'invalid indexing never writes E');
	t.end();
});
tape('scalar precedence, validated empty views and signed target-one pairs', function test(t) {
	var a;
	var e;
	var p;
	t.strictEqual(publicMain('column-major', 'upper', 'convert', 0, null, 1, null, null), 0);
	t.strictEqual(publicMain.ndarray('lower', 'revert', 0, null, NaN, null, null, null, null, null, null, null, null), 0);
	t.throws(function call() {
		publicMain('column-major', 'upper', 'convert', 0, null, 0, null, null);
	}, RangeError, 'LDA validates before empty');
	t.throws(function call() {
		publicMain('column-major', 'upper', 'convert', 2147483648, null, 2147483648, null, null);
	}, RangeError, 'N cap precedes buffers');
	t.throws(function call() {
		publicMain.ndarray('upper', 'convert', 2147483648, null, 0, 0, 0, null, 0, 0, null, 0, 0);
	}, RangeError, 'ndarray N cap');
	t.throws(function call() {
		publicMain('bad', 'upper', 'convert', 0, null, 1, null, null);
	}, TypeError);
	t.throws(function call() {
		publicMain.ndarray('upper', 'bad', 0, null, 0, 0, 0, null, 0, 0, null, 0, 0);
	}, TypeError);
	a = new Float64Array([
		2,
		77,
		-0,
		4
	]);
	e = new Float64Array([
		8,
		9
	]);
	p = new Int32Array([
		-1,
		-2
	]);
	t.strictEqual(publicMain('column-major', 'upper', 'convert', 2, a, 2, e, p), 0);
	t.strictEqual(1 / e[1], -Infinity, 'negative zero storage');
	t.strictEqual(1 / a[2], Infinity, 'canonical positive zero slot');
	t.deepEqual(p, new Int32Array([
		-1,
		-2
	]), 'different negatives stay signed');
	t.strictEqual(publicMain('column-major', 'upper', 'revert', 2, a, 2, e, p), 0);
	t.strictEqual(1 / a[2], -Infinity, 'reversion restores sign');
	t.end();
});
